    void pick(boolean tree){if(busy||!LauncherLock.require(this,()->pick(tree)))return;try{Intent i=tree?new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE):new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"image/jpeg","image/png","image/webp","video/mp4"}).putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true).addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,tree?TREE:FILES);}catch(RuntimeException absent){Toast.makeText(this,"This TV has no file picker. Use paired phone import or desktop Setup.",Toast.LENGTH_LONG).show();}}
