    void next(){if(queue.isEmpty()){status.setText("Review complete. Choose a wallpaper later from your library or playlist.");add.setEnabled(false);return;}Uri uri=queue.remove(0);String mime=getContentResolver().getType(uri);video="video/mp4".equals(mime);if(mime==null||!(video||mime.startsWith("image/"))){status.setText("Unsupported file; choose a JPEG, PNG, WebP or MP4.");return;}busy=true;add.setEnabled(false);status.setText("Preparing a safe still preview…");int token=++generation;boolean movie=video;worker.execute(()->{
        File f=new File(getCacheDir(),"studio-"+UUID.randomUUID()+(movie?".mp4":".image"));Bitmap decoded=null;try{
            long limit=movie?ThemeArchive.MAX_VIDEO:ThemeArchive.MAX_IMAGE;try(InputStream in=getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(f)){if(in==null)throw new IOException();byte[] b=new byte[32768];long size=0;for(int n;(n=in.read(b))!=-1;){if(Thread.currentThread().isInterrupted()||(size+=n)>limit)throw new IOException();out.write(b,0,n);}}
            if(movie){MediaMetadataRetriever m=new MediaMetadataRetriever();try{m.setDataSource(f.getPath());int w=Integer.parseInt(m.extractMetadata(MediaMetadataRetriever.METADATA_KEY_VIDEO_WIDTH)),h=Integer.parseInt(m.extractMetadata(MediaMetadataRetriever.METADATA_KEY_VIDEO_HEIGHT));long ms=Long.parseLong(m.extractMetadata(MediaMetadataRetriever.METADATA_KEY_DURATION));if(!MediaInboxPolicy.video(w,h,ms))throw new IOException();decoded=Build.VERSION.SDK_INT>=27?m.getScaledFrameAtTime(0,MediaMetadataRetriever.OPTION_CLOSEST_SYNC,1280,720):m.getFrameAtTime(0);}finally{m.release();}}
            else{BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;BitmapFactory.decodeFile(f.getPath(),o);if(!MediaInboxPolicy.picture(o.outWidth,o.outHeight))throw new IOException();o.inSampleSize=1;while((long)(o.outWidth/o.inSampleSize)*(o.outHeight/o.inSampleSize)>1920L*1080)o.inSampleSize*=2;o.inJustDecodeBounds=false;decoded=BitmapFactory.decodeFile(f.getPath(),o);if(decoded!=null){try{int orientation=new android.media.ExifInterface(f.getPath()).getAttributeInt(android.media.ExifInterface.TAG_ORIENTATION,1);Matrix matrix=new Matrix();switch(orientation){case 2:matrix.setScale(-1,1);break;case 3:matrix.setRotate(180);break;case 4:matrix.setScale(1,-1);break;case 5:matrix.setRotate(90);matrix.postScale(-1,1);break;case 6:matrix.setRotate(90);break;case 7:matrix.setRotate(270);matrix.postScale(-1,1);break;case 8:matrix.setRotate(270);break;default:break;}if(!matrix.isIdentity()){Bitmap rotated=Bitmap.createBitmap(decoded,0,0,decoded.getWidth(),decoded.getHeight(),matrix,true);if(rotated!=decoded)decoded.recycle();decoded=rotated;}}catch(IOException unsupported){/* WebP/PNG without EXIF keep their decoded orientation. */}}}
            if(decoded==null||!WallpaperSize.accepted(decoded.getWidth(),decoded.getHeight()))throw new IOException();Bitmap ready=decoded;runOnUiThread(()->{if(isDestroyed()||token!=generation){ready.recycle();f.delete();return;}if(prepared!=null)prepared.delete();if(source!=null)source.recycle();source=ready;prepared=f;busy=false;add.setEnabled(true);drawPreview();status.setText(movie?"Silent video ready with still fallback. Framing applies to the still and video; the clip stays silent.":"Picture ready. Choose framing, then add it to the library.");});
        }catch(Exception|OutOfMemoryError bad){if(decoded!=null)decoded.recycle();f.delete();runOnUiThread(()->{if(!isDestroyed()&&token==generation){busy=false;status.setText("Could not prepare this file. Check its format, size and USB access. Nothing was imported.");}});}
    });}
    void framing(){String[] modes={"fill","fit","left","right","top","bottom"};new AlertDialog.Builder(this).setTitle("Picture framing").setSingleChoiceItems(new String[]{"Fill · centered","Fit · show the whole picture","Fill · focus left","Fill · focus right","Fill · focus top","Fill · focus bottom"},Arrays.asList(modes).indexOf(framing),(d,n)->{framing=modes[n];drawPreview();d.dismiss();}).setNegativeButton("Cancel",null).show();}
    Bitmap framed(){Bitmap out=Bitmap.createBitmap(1280,720,Bitmap.Config.RGB_565);Canvas c=new Canvas(out);c.drawColor(0xff101923);float[] box=StudioFraming.bounds(framing,source.getWidth(),source.getHeight(),1280,720);c.drawBitmap(source,null,new RectF(box[0],box[1],box[0]+box[2],box[1]+box[3]),new Paint(3));return out;}
